steps.solution:
d = [[0, 3, 7, 6, 4],
     [3, 0, 4, 7, 6],
     [7, 4, 0, 3, 5],
     [6, 7, 3, 0, 2],
     [4, 6, 5, 2, 0]]
def length(r):
    n = len(r)
    return sum(d[r[i - 1]][r[i]]
               for i in range(n))
r = [0, 2, 1, 4, 3]
for rounds in range(5):
    for i in range(1, 4):
        for j in range(i + 1, 5):
            mid = r[i:j + 1][::-1]
            new = r[:i] + mid + r[j + 1:]
            if length(new) < length(r):
                r = new
print(r, length(r))

